// Package telemetry defines the health reading a ground station sends and how it is validated.
package telemetry

import (
	"errors"
	"fmt"
	"time"
)

// Reading is one health sample from a ground station.
type Reading struct {
	// ReadingID is generated by the station and makes ingestion idempotent:
	// the same reading delivered twice is stored once.
	ReadingID   string    `json:"reading_id"`
	StationID   string    `json:"station_id"`
	Timestamp   time.Time `json:"timestamp"`
	CPUTempC    float64   `json:"cpu_temp_c"`
	SignalSNRdB float64   `json:"signal_snr_db"`
	DiskUsedPct float64   `json:"disk_used_pct"`
	Online      bool      `json:"online"`
}

// ErrInvalid wraps every validation failure so callers can map it to HTTP 400.
var ErrInvalid = errors.New("invalid reading")

// maxClockSkew bounds how far in the future a reading's timestamp may be.
const maxClockSkew = 5 * time.Minute

// Validate checks that a reading is complete and physically plausible.
func (r Reading) Validate(now time.Time) error {
	switch {
	case r.ReadingID == "":
		return fmt.Errorf("%w: reading_id is required", ErrInvalid)
	case r.StationID == "":
		return fmt.Errorf("%w: station_id is required", ErrInvalid)
	case r.Timestamp.IsZero():
		return fmt.Errorf("%w: timestamp is required", ErrInvalid)
	case r.Timestamp.After(now.Add(maxClockSkew)):
		return fmt.Errorf("%w: timestamp is in the future", ErrInvalid)
	case r.CPUTempC < -60 || r.CPUTempC > 150:
		return fmt.Errorf("%w: cpu_temp_c out of range", ErrInvalid)
	case r.DiskUsedPct < 0 || r.DiskUsedPct > 100:
		return fmt.Errorf("%w: disk_used_pct must be between 0 and 100", ErrInvalid)
	}
	return nil
}
